function renderDigraphs(lang) {
  const section = document.getElementById('digraphsSection');
  const grid = document.getElementById('digraphsGrid');
  const note = document.getElementById('digraphsNote');
  const h2 = document.getElementById('digraphsH2');
  if (!section || !grid) return;
  const data = digraphsByLang[lang];
  if (!data || !data.items || !data.items.length) {
    section.classList.add('hidden');
    return;
  }
  const u = (typeof t === 'function') ? t() : { digraphsH2: 'Common Digraphs & Pronunciation' };
  if (h2) h2.textContent = u.digraphsH2 || 'Common Digraphs & Pronunciation';
  grid.innerHTML = data.items.map(d =>
    `<div class="digraph-card"><div class="combo">${d.combo}</div><div class="dsound">${d.sound}</div></div>`
  ).join('');
  if (note) note.innerHTML = data.note || '';
  section.classList.remove('hidden');
}


